"use client"

import { useMemo, useState } from "react"
import { Calculator, CircleDollarSign, Info, Landmark, RotateCcw, Search, ShieldCheck, TrendingUp, Users } from "lucide-react"

const SELF_DEDUCTION = 15_500_000
const DEPENDENT_DEDUCTION = 6_200_000
const SOCIAL_INSURANCE_CAP = 46_800_000
const REGIONAL_MINIMUM = { I: 5_310_000, II: 4_730_000, III: 4_140_000, IV: 3_700_000 } as const
type Region = keyof typeof REGIONAL_MINIMUM

const money = (value: number) => `${Math.round(value).toLocaleString("vi-VN")}đ`
const numberValue = (value: string) => Number(value.replace(/\D/g, "")) || 0

function progressiveTax(income: number) {
  const brackets = [[10_000_000, .05], [20_000_000, .1], [30_000_000, .2], [40_000_000, .3], [Infinity, .35]] as const
  let remaining = Math.max(0, income), tax = 0
  for (const [width, rate] of brackets) { const part = Math.min(remaining, width); tax += part * rate; remaining -= part; if (remaining <= 0) break }
  return tax
}

function insurance(gross: number, basis: number, region: Region) {
  const base = Math.min(basis || gross, SOCIAL_INSURANCE_CAP)
  const unemploymentBase = Math.min(basis || gross, REGIONAL_MINIMUM[region] * 20)
  return { social: base * .08, health: base * .015, unemployment: unemploymentBase * .01 }
}

function ToolHero({ icon, title, description }: { icon: React.ReactNode; title: string; description: string }) {
  return <section className="bg-gradient-to-r from-[#06452f] via-[#087a42] to-[#00b14f] text-white"><div className="mx-auto max-w-6xl px-4 py-10 text-center sm:py-12"><span className="mx-auto grid size-11 place-items-center rounded-2xl bg-white/15 ring-1 ring-white/20">{icon}</span><h1 className="mt-4 text-2xl font-bold sm:text-3xl">{title}</h1><p className="mx-auto mt-2 max-w-2xl text-sm leading-6 text-emerald-50 sm:text-base">{description}</p></div></section>
}

function RegulationNotice({ children }: { children: React.ReactNode }) {
  return <div className="rounded-2xl border border-emerald-100 bg-emerald-50/70 p-4 text-sm leading-6 text-slate-700"><div className="flex gap-3"><Info className="mt-0.5 size-5 shrink-0 text-emerald-600"/><div><b className="text-slate-900">Quy định áp dụng từ 01/01/2026</b><div className="mt-1">{children}</div></div></div></div>
}

function MoneyInput({ label, value, onChange, hint }: { label: string; value: number; onChange: (v:number)=>void; hint?: string }) {
  return <label className="block"><span className="text-sm font-semibold text-slate-800">{label}</span><div className="relative mt-2"><CircleDollarSign className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-emerald-600"/><input inputMode="numeric" value={value ? value.toLocaleString("vi-VN") : ""} onChange={e=>onChange(numberValue(e.target.value))} className="h-12 w-full rounded-xl border border-slate-200 bg-white pl-10 pr-16 font-semibold outline-none transition focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/10"/><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-400">VNĐ</span></div>{hint&&<span className="mt-1.5 block text-xs text-slate-500">{hint}</span>}</label>
}

function RegionSelect({ value, onChange }: { value: Region; onChange:(v:Region)=>void }) {
  return <label className="block"><span className="text-sm font-semibold text-slate-800">Vùng lương tối thiểu</span><select value={value} onChange={e=>onChange(e.target.value as Region)} className="mt-2 h-12 w-full rounded-xl border border-slate-200 bg-white px-3 outline-none focus:border-emerald-500"><option value="I">Vùng I · {money(REGIONAL_MINIMUM.I)}/tháng</option><option value="II">Vùng II · {money(REGIONAL_MINIMUM.II)}/tháng</option><option value="III">Vùng III · {money(REGIONAL_MINIMUM.III)}/tháng</option><option value="IV">Vùng IV · {money(REGIONAL_MINIMUM.IV)}/tháng</option></select></label>
}

function ResultRow({ label, value, strong=false, minus=false }: {label:string;value:number;strong?:boolean;minus?:boolean}) { return <div className={`flex items-center justify-between gap-4 ${strong?"border-t border-white/15 pt-4 text-base":"text-sm"}`}><span className="text-emerald-50">{label}</span><b>{minus&&value>0?"− ":""}{money(value)}</b></div> }

export function GrossNetTool() {
  const [gross,setGross]=useState(30_000_000), [basis,setBasis]=useState(30_000_000), [dependents,setDependents]=useState(0), [region,setRegion]=useState<Region>("I"), [mode,setMode]=useState<"gross"|"net">("gross")
  const result=useMemo(()=>{const calc=(g:number)=>{const ins=insurance(g,basis || g,region), total=ins.social+ins.health+ins.unemployment, taxable=Math.max(0,g-total-SELF_DEDUCTION-dependents*DEPENDENT_DEDUCTION), tax=progressiveTax(taxable);return {gross:g,ins,total,taxable,tax,net:g-total-tax}};if(mode==="gross")return calc(gross);let low=gross,high=gross*2.5+20_000_000;for(let i=0;i<45;i++){const mid=(low+high)/2;if(calc(mid).net<gross)low=mid;else high=mid}return calc(high)},[gross,basis,dependents,region,mode])
  return <><ToolHero icon={<Calculator/>} title="Tính lương Gross – Net chuẩn 2026" description="Ước tính lương thực nhận, bảo hiểm bắt buộc và thuế thu nhập cá nhân theo từng khoản."/><section className="mx-auto max-w-6xl space-y-6 px-4 py-8 sm:py-10"><RegulationNotice>Giảm trừ bản thân <b>{money(SELF_DEDUCTION)}/tháng</b>, mỗi người phụ thuộc <b>{money(DEPENDENT_DEDUCTION)}/tháng</b>; biểu thuế lũy tiến 5 bậc và mức lương tối thiểu vùng năm 2026.</RegulationNotice><div className="grid gap-6 lg:grid-cols-[1.08fr_.92fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div className="grid grid-cols-2 rounded-xl bg-slate-100 p-1"><button onClick={()=>setMode("gross")} className={`rounded-lg py-2.5 text-sm font-bold ${mode==="gross"?"bg-white text-emerald-700 shadow-sm":"text-slate-500"}`}>Gross → Net</button><button onClick={()=>setMode("net")} className={`rounded-lg py-2.5 text-sm font-bold ${mode==="net"?"bg-white text-emerald-700 shadow-sm":"text-slate-500"}`}>Net → Gross</button></div><div className="mt-6 grid gap-5 sm:grid-cols-2"><MoneyInput label={mode==="gross"?"Lương Gross hàng tháng":"Lương Net mong muốn"} value={gross} onChange={setGross}/><MoneyInput label="Mức lương đóng bảo hiểm" value={basis} onChange={setBasis} hint="Để trống hoặc bằng lương chính thức nếu đóng trên toàn bộ lương."/><RegionSelect value={region} onChange={setRegion}/><label><span className="text-sm font-semibold text-slate-800">Số người phụ thuộc</span><div className="relative mt-2"><Users className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-emerald-600"/><select value={dependents} onChange={e=>setDependents(Number(e.target.value))} className="h-12 w-full rounded-xl border border-slate-200 bg-white pl-10 pr-3 outline-none focus:border-emerald-500">{Array.from({length:11},(_,i)=><option key={i} value={i}>{i} người</option>)}</select></div></label></div><button className="mt-6 w-full rounded-xl bg-[#00b14f] py-3 font-bold text-white transition hover:bg-[#009b45] active:scale-[.99]">Cập nhật kết quả</button></div><div className="rounded-2xl bg-[#073f2d] p-5 text-white shadow-sm sm:p-7"><p className="text-sm text-emerald-100">{mode==="gross"?"Thu nhập thực nhận ước tính":"Lương Gross cần thỏa thuận"}</p><p className="mt-2 text-3xl font-extrabold sm:text-4xl">{money(mode==="gross"?result.net:result.gross)}</p><div className="mt-6 space-y-3 border-t border-white/15 pt-5"><ResultRow label="Bảo hiểm xã hội (8%)" value={result.ins.social} minus/><ResultRow label="Bảo hiểm y tế (1,5%)" value={result.ins.health} minus/><ResultRow label="Bảo hiểm thất nghiệp (1%)" value={result.ins.unemployment} minus/><ResultRow label="Thu nhập tính thuế" value={result.taxable}/><ResultRow label="Thuế TNCN ước tính" value={result.tax} minus/><ResultRow strong label={mode==="gross"?"Lương Net":"Lương Gross"} value={mode==="gross"?result.net:result.gross}/></div></div></div><p className="text-xs leading-5 text-slate-500">Kết quả mang tính tham khảo cho cá nhân cư trú có hợp đồng lao động. Phụ cấp miễn thuế, khoản đóng góp tự nguyện và trường hợp đặc biệt có thể làm thay đổi số thực nhận.</p></section></>
}

export function PersonalIncomeTaxTool() {
  const [income,setIncome]=useState(40_000_000),[insuranceBasis,setInsuranceBasis]=useState(40_000_000),[dependents,setDependents]=useState(0),[region,setRegion]=useState<Region>("I")
  const result=useMemo(()=>{const ins=insurance(income,insuranceBasis,region),insuranceTotal=ins.social+ins.health+ins.unemployment,dependent=dependents*DEPENDENT_DEDUCTION,taxable=Math.max(0,income-insuranceTotal-SELF_DEDUCTION-dependent),tax=progressiveTax(taxable);return{ins,insuranceTotal,dependent,taxable,tax}},[income,insuranceBasis,dependents,region])
  return <><ToolHero icon={<Landmark/>} title="Tính thuế thu nhập cá nhân 2026" description="Xem rõ các khoản giảm trừ, thu nhập tính thuế và số thuế tạm tính mỗi tháng."/><section className="mx-auto max-w-6xl space-y-6 px-4 py-8"><RegulationNotice>Áp dụng giảm trừ bản thân <b>{money(SELF_DEDUCTION)}</b>, người phụ thuộc <b>{money(DEPENDENT_DEDUCTION)}</b> và biểu thuế tiền lương 5 bậc của kỳ tính thuế 2026.</RegulationNotice><div className="grid gap-6 lg:grid-cols-[1fr_.9fr]"><div className="rounded-2xl border bg-white p-5 shadow-sm sm:p-6"><h2 className="text-lg font-bold text-slate-900">Thông tin thu nhập</h2><div className="mt-5 grid gap-5 sm:grid-cols-2"><MoneyInput label="Thu nhập Gross hàng tháng" value={income} onChange={setIncome}/><MoneyInput label="Lương đóng bảo hiểm" value={insuranceBasis} onChange={setInsuranceBasis}/><RegionSelect value={region} onChange={setRegion}/><label><span className="text-sm font-semibold">Số người phụ thuộc</span><select value={dependents} onChange={e=>setDependents(Number(e.target.value))} className="mt-2 h-12 w-full rounded-xl border border-slate-200 bg-white px-3">{Array.from({length:11},(_,i)=><option key={i}>{i}</option>)}</select></label></div><button className="mt-6 rounded-xl bg-[#00b14f] px-6 py-3 font-bold text-white">Tính thuế TNCN</button></div><div className="rounded-2xl border bg-white p-5 shadow-sm sm:p-6"><p className="text-sm text-slate-500">Thuế TNCN tạm tính mỗi tháng</p><p className="mt-1 text-3xl font-extrabold text-emerald-600">{money(result.tax)}</p><div className="mt-5 space-y-3 text-sm"><div className="flex justify-between"><span>Thu nhập Gross</span><b>{money(income)}</b></div><div className="flex justify-between"><span>Bảo hiểm bắt buộc</span><b>− {money(result.insuranceTotal)}</b></div><div className="flex justify-between"><span>Giảm trừ bản thân</span><b>− {money(SELF_DEDUCTION)}</b></div><div className="flex justify-between"><span>Giảm trừ người phụ thuộc</span><b>− {money(result.dependent)}</b></div><div className="flex justify-between border-t pt-3"><span>Thu nhập tính thuế</span><b>{money(result.taxable)}</b></div></div></div></div><div className="overflow-hidden rounded-2xl border bg-white"><div className="border-b px-5 py-4"><h2 className="font-bold">Biểu thuế lũy tiến từng phần 2026</h2></div><div className="grid grid-cols-3 bg-slate-50 px-5 py-3 text-xs font-bold text-slate-500"><span>Bậc</span><span>Thu nhập tính thuế/tháng</span><span>Thuế suất</span></div>{[["1","Đến 10 triệu","5%"],["2","Trên 10–30 triệu","10%"],["3","Trên 30–60 triệu","20%"],["4","Trên 60–100 triệu","30%"],["5","Trên 100 triệu","35%"]].map(r=><div key={r[0]} className="grid grid-cols-3 border-t px-5 py-3 text-sm"><span>{r[0]}</span><span>{r[1]}</span><b className="text-emerald-700">{r[2]}</b></div>)}</div></section></>
}

export function UnemploymentBenefitTool() {
  const [salary,setSalary]=useState(12_000_000),[months,setMonths]=useState(36),[region,setRegion]=useState<Region>("I")
  const result=useMemo(()=>{const monthly=Math.min(salary*.6,REGIONAL_MINIMUM[region]*5),benefitMonths=months<12?0:Math.min(12,3+Math.floor((months-36)/12));return{monthly,benefitMonths:Math.max(months>=12?3:0,benefitMonths)}},[salary,months,region])
  return <><ToolHero icon={<ShieldCheck/>} title="Tính mức hưởng bảo hiểm thất nghiệp 2026" description="Ước tính trợ cấp hàng tháng, thời gian được hưởng và tổng quyền lợi dự kiến."/><section className="mx-auto max-w-6xl space-y-6 px-4 py-8"><RegulationNotice>Mức hưởng mỗi tháng bằng <b>60% bình quân tiền lương đóng BHTN của 6 tháng liền kề</b>, nhưng không vượt quá 5 lần lương tối thiểu vùng.</RegulationNotice><div className="grid gap-6 lg:grid-cols-[1fr_.9fr]"><div className="rounded-2xl border bg-white p-5 shadow-sm sm:p-6"><div className="grid gap-5 sm:grid-cols-2"><MoneyInput label="Bình quân lương đóng BHTN 6 tháng" value={salary} onChange={setSalary}/><label><span className="text-sm font-semibold">Tổng thời gian đóng BHTN chưa hưởng</span><div className="relative mt-2"><input type="number" min={0} value={months} onChange={e=>setMonths(Math.max(0,Number(e.target.value)))} className="h-12 w-full rounded-xl border border-slate-200 px-3 pr-16 font-semibold"/><span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-400">tháng</span></div></label><RegionSelect value={region} onChange={setRegion}/></div><button className="mt-6 rounded-xl bg-[#00b14f] px-6 py-3 font-bold text-white">Tính bảo hiểm</button></div><div className="rounded-2xl bg-[#073f2d] p-6 text-white"><p className="text-sm text-emerald-100">Mức hưởng mỗi tháng</p><p className="mt-2 text-3xl font-extrabold">{money(result.monthly)}</p><div className="mt-6 grid grid-cols-2 gap-3"><div className="rounded-xl bg-white/10 p-4"><span className="text-xs text-emerald-100">Thời gian hưởng</span><p className="mt-1 text-xl font-bold">{result.benefitMonths} tháng</p></div><div className="rounded-xl bg-white/10 p-4"><span className="text-xs text-emerald-100">Tổng dự kiến</span><p className="mt-1 text-xl font-bold">{money(result.monthly*result.benefitMonths)}</p></div></div>{months<12&&<p className="mt-4 rounded-lg bg-amber-300/15 p-3 text-sm text-amber-100">Cần đóng BHTN đủ tối thiểu 12 tháng để đủ điều kiện về thời gian đóng.</p>}</div></div></section></>
}

const salaryData=[] as { role: string; field: string; location: string; junior: number[]; middle: number[]; senior: number[]; samples: number; }[]

export function SalaryLookupTool(){const[q,setQ]=useState(""),[level,setLevel]=useState<"junior"|"middle"|"senior">("middle");const rows=salaryData.filter(x=>(x.role+x.field+x.location).toLowerCase().includes(q.toLowerCase()));return <><ToolHero icon={<TrendingUp/>} title="Tra cứu mức lương thị trường" description="Tham khảo khoảng lương theo vị trí, cấp bậc và khu vực để chuẩn bị tốt hơn khi ứng tuyển."/><section className="mx-auto max-w-6xl px-4 py-8"><div className="rounded-2xl border bg-white p-5 shadow-sm sm:p-6"><div className="grid gap-4 md:grid-cols-[1fr_220px_auto]"><label className="relative"><Search className="absolute left-3.5 top-1/2 size-4 -translate-y-1/2 text-slate-400"/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Nhập vị trí hoặc lĩnh vực..." className="h-12 w-full rounded-xl border border-slate-200 pl-10 pr-3 outline-none focus:border-emerald-500"/></label><select value={level} onChange={e=>setLevel(e.target.value as typeof level)} className="h-12 rounded-xl border border-slate-200 bg-white px-3"><option value="junior">Dưới 2 năm</option><option value="middle">2–5 năm</option><option value="senior">Trên 5 năm</option></select><button className="h-12 rounded-xl bg-[#00b14f] px-6 font-bold text-white">Tra cứu</button></div></div><div className="mt-6 space-y-4">{rows.length?rows.map(item=>{const values=item[level];return <article key={item.role} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition hover:border-emerald-300 hover:shadow-md"><div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><h2 className="text-lg font-bold text-slate-900">{item.role}</h2><p className="mt-1 text-sm text-slate-500">{item.field} · {item.location} · {item.samples} mẫu tin</p></div><div className="sm:text-right"><span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Mức lương phổ biến</span><p className="mt-1 text-xl font-extrabold text-emerald-600">{values[0]}–{values[1]} triệu/tháng</p></div></div><div className="mt-5 grid grid-cols-3 gap-3"><div className="rounded-xl bg-slate-50 p-3"><span className="text-xs text-slate-500">Thấp</span><p className="font-bold">{values[0]} triệu</p></div><div className="rounded-xl bg-emerald-50 p-3"><span className="text-xs text-emerald-700">Trung vị</span><p className="font-bold text-emerald-700">{values[2]} triệu</p></div><div className="rounded-xl bg-slate-50 p-3"><span className="text-xs text-slate-500">Cao</span><p className="font-bold">{values[1]} triệu</p></div></div></article>}):<div className="rounded-2xl border border-dashed bg-white p-10 text-center"><Search className="mx-auto size-10 text-slate-300"/><h2 className="mt-3 font-bold">Chưa tìm thấy dữ liệu phù hợp</h2><p className="mt-1 text-sm text-slate-500">Dữ liệu sẽ hiển thị khi có thống kê.</p><button onClick={()=>setQ("")} className="mt-4 inline-flex items-center gap-2 text-sm font-bold text-emerald-700"><RotateCcw className="size-4"/>Xem tất cả vị trí</button></div>}</div><p className="mt-5 text-xs leading-5 text-slate-500">Chưa có dữ liệu thống kê mức lương.</p></section></>}
