function Filter({ title, options }: { title: string; options: string[] }) {
  const [selected, setSelected] = useState<string[]>([]);
  const toggle = (x: string) =>
    setSelected((s) => (s.includes(x) ? s.filter((y) => y !== x) : [...s, x]));
  const specialties = [
    "Chuyên môn Kinh doanh/Bán hàng",
    "Sales Representative/Phát triển kinh doanh",
    "Trợ lý kinh doanh",
    "Kinh doanh quà tặng/in ấn",
    "Kinh doanh nông sản",
    "Account Executive",
    "Sales Dịch vụ kế toán",
  ];
  return (
    <div className="mt-5 border-t pt-5">
      <h3 className="font-bold">{title}</h3>
      <div className="mt-3 space-y-3">
        {options.map((x) => (
          <div key={x}>
            <label className="flex cursor-pointer items-center gap-2 text-sm text-slate-600">
              <input
                checked={selected.includes(x)}
                onChange={() => toggle(x)}
                type="checkbox"
                className="size-4 rounded accent-[#00b14f]"
              />
              {x}
              {title === "Lọc theo danh mục nghề" && x === options[1] && (
                <span className="text-xs text-slate-400">(559)</span>
              )}
            </label>
            {title === "Lọc theo danh mục nghề" && x === options[1] && (
              <div className="ml-8 mt-3 space-y-2">
                {specialties.map((s) => (
                  <label
                    key={s}
                    className="flex cursor-pointer items-center gap-2 text-xs text-slate-600"
                  >
                    <input
                      checked={selected.includes(s)}
                      onChange={() => toggle(s)}
                      type="checkbox"
                      className="size-3.5 rounded accent-[#00b14f]"
                    />
                    <span className="rounded-full border border-slate-300 px-2.5 py-1">
                      {s}
                    </span>
                  </label>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
function GrossNet() {
  const [gross, setGross] = useState(30000000);
  const [dependents, setDependents] = useState(0);
  const insurance = Math.round(gross * 0.105);
  const taxable = Math.max(
    0,
    gross - insurance - 11000000 - dependents * 4400000,
  );
  const tax = Math.round(taxable * 0.1);
  return (
    <Shell>
      <Hero
        icon={<Calculator />}
        title="Tính lương Gross – Net"
        desc="Ước tính thu nhập thực nhận theo mức lương và người phụ thuộc."
      />
      <section className="mx-auto grid max-w-4xl gap-6 px-4 py-10 md:grid-cols-2">
        <div className="rounded-2xl bg-white p-6 shadow-sm">
          <label className="text-sm font-bold">
            Lương Gross (VNĐ/tháng)
            <input
              type="number"
              value={gross}
              onChange={(e) => setGross(Number(e.target.value))}
              className="mt-2 w-full rounded-xl border p-3 text-lg font-bold outline-none focus:border-[#00b14f]"
            />
          </label>
          <label className="mt-5 block text-sm font-bold">
            Số người phụ thuộc
            <select
              value={dependents}
              onChange={(e) => setDependents(Number(e.target.value))}
              className="mt-2 w-full rounded-xl border p-3 font-normal"
            >
              <option value="0">0 người</option>
              <option value="1">1 người</option>
              <option value="2">2 người</option>
            </select>
          </label>
          <button className="mt-6 w-full rounded-xl bg-[#00b14f] py-3 text-sm font-bold text-white">
            Cập nhật kết quả
          </button>
        </div>
        <div className="rounded-2xl bg-[#063c27] p-6 text-white shadow-sm">
          <p className="text-sm text-emerald-100">
            Thu nhập thực nhận ước tính
          </p>
          <p className="mt-2 text-3xl font-extrabold">
            {(gross - insurance - tax).toLocaleString("vi-VN")}đ
          </p>
          <div className="mt-7 space-y-3 border-t border-white/15 pt-5 text-sm">
            <p className="flex justify-between">
              <span>Bảo hiểm bắt buộc</span>
              <b>-{insurance.toLocaleString("vi-VN")}đ</b>
            </p>
            <p className="flex justify-between">
              <span>Thuế TNCN ước tính</span>
              <b>-{tax.toLocaleString("vi-VN")}đ</b>
            </p>
            <p className="flex justify-between">
              <span>Thu nhập chịu thuế</span>
              <b>{taxable.toLocaleString("vi-VN")}đ</b>
            </p>
          </div>
        </div>
      </section>
    </Shell>
  );
}
